local _, ns = ...
local L = ns.L

-- Options/Welcome.lua: What's New, by version (WN<id>_<n>), newest first; English beside Locales/enUS.lua.
L["WN100_1_TITLE"] = "Profession side tabs"
L["WN100_1_TEXT"] = "The professions side tabs wear the classic look and start where the spellbook's do, with What's Training's tab under them, fading on hover with them."
L["WN100_2_TITLE"] = "Who"
L["WN100_2_TEXT"] = "With \"Group finder\" unchecked, the game's group finder keeps its own Who tab and the social window shows none. To have Who in the social window instead, turn on \"Who tab in the social window\" under Social in the options."
L["WN100_3_TITLE"] = "Windows"
L["WN100_3_TEXT"] = "Collections, Legacy, and the group finder are each our classic window or the game's own, our windows open past a neighbor's side tabs, and in Edit Mode a window another addon moves is grayed out from the start."
L["WN100_4_TITLE"] = "Smaller fixes"
L["WN100_4_TEXT"] = "What's Training on the spellbook wears the professions' black marble, the spellbook's options arrow keeps to the right with the search hidden, and another addon's button no longer covers the professions window's lock."
L["WN99_1_TITLE"] = "Share Quest"
L["WN99_1_TEXT"] = "Share Quest in the quest log shares your quest with your group again."
L["WN99_2_TITLE"] = "Options drop downs"
L["WN99_2_TEXT"] = "The drop downs in the game's Options no longer show a stretched button inside them under a textured custom theme."
L["WN99_3_TITLE"] = "In a fight"
L["WN99_3_TEXT"] = "In a fight, action bars no longer jump when a window opens with a micro button hidden, the professions book opened from the spellbook keeps the spellbook's place with no empty second pane, and inspecting a player's talents from their menu opens only our window, with no error."
L["WN99_4_TITLE"] = "Chat"
L["WN99_4_TEXT"] = "The chat and its tabs no longer vanish when another addon resizes the chat."
L["WN99_5_TITLE"] = "Drop downs and What's Training"
L["WN99_5_TEXT"] = "Under a textured custom theme, the drop downs in our options are drawn whole again, and What's Training on the professions book wears the spellbook's black marble with no lines across the list."
L["WN98_1_TITLE"] = "Bag icons on empty slots"
L["WN98_1_TEXT"] = "In One bag, each empty slot now shows a faded icon of the bag it belongs to, so a quiver's slots are easy to spot. Turn it on in the options (/fcui): One bag, under Bags. Plain empty slots, just under it, makes them all alike again."
L["WN98_2_TITLE"] = "Class colors in battlegrounds"
L["WN98_2_TEXT"] = "Enemy players' nameplates now show their class color in battlegrounds and dungeons, where the game hides their class and they showed red."
L["WN98_3_TITLE"] = "Bags stay put"
L["WN98_3_TEXT"] = "Bags moved in Edit Mode now stay where you leave them. Bags you placed before this version stay where they are."
L["WN98_4_TITLE"] = "Windows on top"
L["WN98_4_TEXT"] = "A window you drag over the quest log or the spellbook now goes over it, and the spellbook's icons no longer show through."
L["WN98_5_TITLE"] = "Group finder tabs"
L["WN98_5_TEXT"] = "The group finder and a window another addon opens from its side tabs now share one spot, so switching tabs no longer jumps, and dragging either moves both."
L["WN97_1_TITLE"] = "No gap at max level"
L["WN97_1_TEXT"] = "At max level, with no experience or reputation bar showing, the bars above the main bar now sit down on the thin bar where experience was, as on Era."
L["WN97_2_TITLE"] = "Legacy challenges"
L["WN97_2_TEXT"] = "The Challenges list nests its sections as the game's own window does, and its search finds any word a challenge shows, from its sections to its steps."
L["WN97_3_TITLE"] = "Other addons' side tabs"
L["WN97_3_TEXT"] = "Side tabs that other addons add to the group finder, like LFG Forever's, now look like ours and line up under them."
L["WN96_1_TITLE"] = "Era's Loot Rolls"
L["WN96_1_TEXT"] = "/loot opens Era's Loot Rolls window: every drop with its winner and roll, and + on a drop lists everyone's rolls. Drag the tab under it for the height, or its corner for both ways."
L["WN96_2_TITLE"] = "Appear Offline"
L["WN96_2_TEXT"] = "The classic social window's status menu now has Appear Offline, beside Available, Away and Busy."
L["WN96_3_TITLE"] = "Social unchecked"
L["WN96_3_TEXT"] = "Unchecking Social on the All windows page now gives you the game's own social window, with none of our tabs in it."
L["WN95_1_TITLE"] = "One bag per profile"
L["WN95_1_TEXT"] = "Profiles now keep One bag, so characters on different profiles keep their own bag mode. Before, a change on one character applied to all of them. Turn it on in the options (/fcui) on each profile that wants it: One bag, under Bags."
L["WN95_2_TITLE"] = "Stats in a fight"
L["WN95_2_TEXT"] = "The character window's stats no longer stand empty when first opened in a fight, and attributes, health, armor, crit, haste and dodge follow buffs during a fight."
L["WN94_1_TITLE"] = "Master loot"
L["WN94_1_TEXT"] = "As master looter, clicking an item in the classic loot window lists your group under Assign Loot again, in Era's look under the item, and Request Roll starts a roll on it."
L["WN93_1_TITLE"] = "Nameplate styles"
L["WN93_1_TEXT"] = "Classic is now in the game's nameplate Style list (Options, Nameplates). Picking one of the game's styles turns our nameplates off so that style shows; Classic brings ours back."
L["WN93_2_TITLE"] = "Loot history"
L["WN93_2_TEXT"] = "The loot history window (/loot) wears the classic frame with your theme. Drag its corner to size it both ways; right-click the corner for its own size."
L["WN93_3_TITLE"] = "Stance and pet backing"
L["WN93_3_TEXT"] = "The backing behind the stance and pet bars follows the Action bars theme, as the bar's own art does."
L["WN93_4_TITLE"] = "Trade skill quantity"
L["WN93_4_TEXT"] = "Clicking the quantity box in the classic trade skill window selects the number, so typing replaces it, as in Era."
L["WN92_1_TITLE"] = "Stance and pet bars"
L["WN92_1_TEXT"] = "The stance, pet and possess bars sit where Era puts them: on top of the main bar on Era's own backing, or just above bar 2 when it is on. Drag one in edit mode to place it yourself."
L["WN92_2_TITLE"] = "Totem bar"
L["WN92_2_TEXT"] = "The shaman's totem bar sits at the stance bar's spot on top of the main bar and stays there after every load."
L["WN92_3_TITLE"] = "Action bars"
L["WN92_3_TEXT"] = "Turning off bar 2 or bar 3 leaves the other where it was."
L["WN92_4_TITLE"] = "Profession macros"
L["WN92_4_TEXT"] = "A macro can press Create in the classic trade skill window, such as a quick enchant macro: /run ClassicUIForeverTradeSkill.CreateButton:Click()"
L["WN91_1_TITLE"] = "Quest tracking"
L["WN91_1_TEXT"] = "Untracked quests coming back to the tracker? That is the game's Automatic Quest Tracking. Uncheck Automatic quest tracking under Quests (/fcui) and they stay off."
L["WN91_2_TITLE"] = "Raid panel"
L["WN91_2_TEXT"] = "The group panel at the screen's left edge can stay hidden until you move the mouse over it. Turn it on in the options (/fcui): Raid panel on hover, under Unit frames."
L["WN90_1_TITLE"] = "Quest colors"
L["WN90_1_TEXT"] = "All your quests in yellow? That is the game's Quest Difficulty Color setting, turned off. It is now in the options (/fcui) too: check Quest difficulty colors under Quests."
L["WN90_2_TITLE"] = "Pet tab"
L["WN90_2_TEXT"] = "It lists the stats pets actually have: health, speed, crit chance, haste, power, damage, defense and armor."
L["WN90_3_TITLE"] = "Bags"
L["WN90_3_TEXT"] = "Bags you drop onto the classic bar in edit mode stay there after you log out, and a Lua error some addons caused when refreshing the bags is gone."
L["WN90_4_TITLE"] = "Collections"
L["WN90_4_TEXT"] = "In Appearances, the preview fits your whole character, and trying another look in the same slot keeps the camera where you left it."
L["WN90_5_TITLE"] = "Quest log"
L["WN90_5_TEXT"] = "It no longer slows down while another addon loads item data."
L["WN89_1_TITLE"] = "No achievement box"
L["WN89_1_TEXT"] = "The game's box that pops up as you complete an achievement (on Forever, a Legacy challenge) or a step of one is gone, as 1.x had none. To have it back, turn it on in the options (/fcui): check Achievement toast under Other."
L["WN89_2_TITLE"] = "Skills tab"
L["WN89_2_TEXT"] = "Its lower pane no longer stays up when the character window opens on another tab."
L["WN88_1_TITLE"] = "Pets"
L["WN88_1_TEXT"] = "Summoning another pet no longer freezes the game for a moment."
L["WN88_2_TITLE"] = "Quest log"
L["WN88_2_TEXT"] = "Abandoning a quest plays its sound only once you pick Yes."
L["WN88_3_TITLE"] = "Professions"
L["WN88_3_TEXT"] = "The professions book counts gear such as a fishing pole in each skill's bonus."
L["WN87_1_TITLE"] = "Unit frame tooltips"
L["WN87_1_TEXT"] = "The line saying to right-click for frame settings is gone from unit frame tooltips, as in Era. To see it again, turn off Hide right-click hint in the options (/fcui), under Unit frames."
L["WN87_2_TITLE"] = "Bags"
L["WN87_2_TEXT"] = "The backpack keeps its classic picture when bags change."
L["WN87_3_TITLE"] = "Character window"
L["WN87_3_TEXT"] = "The Hit Chance rows show their tooltip again."
L["WN87_4_TITLE"] = "Vendors"
L["WN87_4_TEXT"] = "The repair buttons show Era's icons."
L["WN87_5_TITLE"] = "XP bar"
L["WN87_5_TEXT"] = "The XP bar sits where Era's does and is just as tall."
L["WN86_1_TITLE"] = "Action bar addons"
L["WN86_1_TEXT"] = "With an action bar addon that takes over the game's bars, its bars keep their buttons and their look, Masque skins included, and the game menu's Log Out and Exit Game work again."
L["WN86_2_TITLE"] = "Classic bar turned off"
L["WN86_2_TEXT"] = "Pet and stance buttons and the character button get their own look back."
L["WN85_1_TITLE"] = "Options window"
L["WN85_1_TEXT"] = "The game's Options window no longer lowers the frame rate while it is open."
L["WN85_2_TITLE"] = "Talents"
L["WN85_2_TEXT"] = "A talent locked until its tree has enough points says in red how many it needs, as in Era."
L["WN85_3_TITLE"] = "XP bar"
L["WN85_3_TEXT"] = "The game's own segment lines no longer show over the XP bar after logging in during a fight."
L["WN85_4_TITLE"] = "Professions"
L["WN85_4_TEXT"] = "The professions book keeps each profession's spells together when opened during a fight, and with TradeSkillMaster on, the professions window no longer jumps right as a fight ends."
L["WN84_1_TITLE"] = "Merchant and trainer windows"
L["WN84_1_TEXT"] = "The merchant and trainer windows can now be moved and sized. Click the lock beside the close button, then drag the window or its corner. They share one place and size with the quest and gossip windows, and ClassicUI Forever Windows shows windows that share a place as one row and one box."
L["WN84_2_TITLE"] = "Tracker and the map's quest settings"
L["WN84_2_TEXT"] = "Quest titles in the classic tracker, the quest log and the map's quest lists follow the map's Quest Difficulty Color setting (plain when it is off), and that setting and Show Quest Levels show at once, with no reload."
L["WN84_3_TITLE"] = "Fixes"
L["WN84_3_TEXT"] = "A quest title in the classic tracker keeps its color after the mouse leaves it, the Classic combined map's scroll bars fit their places while the map is windowed, the map key shuts that map on every character, and the minimap button stays in MinimapButtonBag Reborn's bag."
L["WN84_4_TITLE"] = "Skills tab"
L["WN84_4_TEXT"] = "A skill going up during a fight no longer causes an error while the Skills tab shows a weapon skill."
L["WN83_1_TITLE"] = "Skills tab and auction house"
L["WN83_1_TEXT"] = "The Skills tab no longer causes an error for a character with a bonus to Defense, and the auction house's bid button no longer covers the end of the copper box."
L["WN83_2_TITLE"] = "Raid panel and controller"
L["WN83_2_TEXT"] = "The raid panel's closed tab sits at the screen's edge when you join a group during a fight, and the Gamepad options show your controller's own View and Menu icons."
L["WN82_1_TITLE"] = "Share Quest with a full screen map"
L["WN82_1_TEXT"] = "Sharing a quest from the quest log no longer leaves the world map open when you keep the map full screen."
L["WN82_2_TITLE"] = "Share Quest"
L["WN82_2_TEXT"] = "Share Quest in the quest log shares the quest, instead of saying to share it from the world map."
L["WN81_1_TITLE"] = "Crafting cost and profit"
L["WN81_1_TEXT"] = "With Auctionator, the classic trade skill window shows what a recipe costs to craft and its profit above the reagents, and a Search button for the reagents while the auction house is open."
L["WN81_2_TITLE"] = "Class colors for friends or enemies"
L["WN81_2_TEXT"] = "Friendly players and Enemy players are separate boxes under the nameplates' Class colors, Class colored name box and Class colored health, so class colors can be for one side only. The class color options themselves are off by default: turn them on in the options (/fcui)."
L["WN81_3_TITLE"] = "Controller autorun"
L["WN81_3_TEXT"] = "On the classic layout, autorun is on the left stick's press by default, and a button picked for autorun or chat also works on a stick the cursor clicks with."
L["WN81_4_TITLE"] = "Fixes"
L["WN81_4_TEXT"] = "What's Training's list in the double pane trade skill window sits on one background, and the pet frame's health and focus bars fill their slots."
L["WN80_1_TITLE"] = "Controller on the classic layout (work in progress)"
L["WN80_1_TEXT"] = "Play the classic bars with a controller while the game's gamepad interface is off: the d-pad and face buttons fire Action Bar 1, or the other bars with a trigger held. Off by default; a box asks the first time you use a controller, and it is in the options (/fcui), under Gamepad. Still in progress: bags, the map and menus need the game's cursor for now."
L["WN80_2_TITLE"] = "Raid panel in fights"
L["WN80_2_TEXT"] = "The raid and party panel keeps its rows in place when the group changes during a fight, and its pull-out tab no longer vanishes when you close the panel in one."
L["WN80_3_TITLE"] = "Pet training"
L["WN80_3_TEXT"] = "The trainer window no longer keeps an old list, so skills your pet already knows are not left listed as learnable."
L["WN79_1_TITLE"] = "Raid panel in fights"
L["WN79_1_TEXT"] = "The raid and party panel no longer causes an error when your group changes during a fight, for example when a party member levels up. It catches up as the fight ends."
L["WN78_1_TITLE"] = "Classic raid panel"
L["WN78_1_TEXT"] = "The raid and party panel at the screen's left edge has the classic look and order, and every control of the game's is still in it. Its world marker button switches the target icons to marking the ground."
L["WN78_2_TITLE"] = "Raid panel edge"
L["WN78_2_TEXT"] = "Closed, the panel shows only its arrow tab. Raid panel edge when closed keeps its frame along the screen's edge, as Era's does. Off by default; turn it on in the options (/fcui), under Unit frames."
L["WN78_3_TITLE"] = "Small fixes"
L["WN78_3_TEXT"] = "The loot window opens at once and no longer jumps when you click an item with full bags. The guild tab's and the Communities window's buttons no longer stay clickable after their window closed in a fight."
L["WN77_1_TITLE"] = "Trainer search"
L["WN77_1_TEXT"] = "A trainer's window has a search box beside its filter. It lists only the spells and recipes whose name holds the words. Search box, under Trainer window in the options (/fcui), turns it off."
L["WN77_2_TITLE"] = "What's Training in its own window"
L["WN77_2_TEXT"] = "The spellbook's training tab can open What's Training's own window instead of a page in the book; the window closes with the book. Off by default; turn it on in the options (/fcui), under Spellbook."
L["WN77_3_TITLE"] = "Class colored guild names"
L["WN77_3_TEXT"] = "Guild roster names can show in their class colors. Off by default; turn it on in the options (/fcui), under Guild roster."
L["WN77_4_TITLE"] = "Classic bank"
L["WN77_4_TEXT"] = "The bank has the classic slot plates and rivets at their classic spacing, in a shorter window."
L["WN77_5_TITLE"] = "Search boxes"
L["WN77_5_TEXT"] = "The quest log's and the professions' search boxes have the classic input look."
L["WN77_6_TITLE"] = "Notices over the chat"
L["WN77_6_TEXT"] = "Friend toasts and the world refresh notice stand above the chat's tabs. On a taller chat they had covered its text and tabs."
L["WN77_7_TITLE"] = "Small fixes"
L["WN77_7_TEXT"] = "Forever Quest Tint covers the whole quest page on the map, not a strip under the title. Closing a bank or vendor no longer flicks open bags aside for a moment, and /fstack no longer lists the addon's hidden helper frames."
L["WN76_1_TITLE"] = "Quest log search"
L["WN76_1_TEXT"] = "The double pane quest log has a search box in its header. It lists the quests whose name or zone holds the words."
L["WN76_2_TITLE"] = "Sort by difficulty"
L["WN76_2_TEXT"] = "Every recipe of a profession in one run, orange first, then yellow, green and gray. Turn it on in a profession window's Filter menu or in the options (/fcui), under Professions."
L["WN76_3_TITLE"] = "Classic close buttons"
L["WN76_3_TEXT"] = "The guild bank and the flight master's map have the classic X."
L["WN75_1_TITLE"] = "Item link tooltip"
L["WN75_1_TEXT"] = "The X on an item link's tooltip is the classic one, on its classic spot."
L["WN75_2_TITLE"] = "Pet abilities on the cursor"
L["WN75_2_TEXT"] = "After a pet change, a pet ability the game will not keep a copy of is placed once, not again and again. For some pets that had put icons on the cursor and stalled the game."
L["WN74_1_TITLE"] = "Spellbook training page"
L["WN74_1_TEXT"] = "The spellbook's training page works with What's Training 11.3. That version had made the tab open What's Training's own window instead of the list in the book."
L["WN74_2_TITLE"] = "Share Quest from the quest log"
L["WN74_2_TEXT"] = "Share Quest in the quest log shares quests outside the zone you stand in too, dungeon quests among them, and leaves the world map shut afterward."
L["WN73_1_TITLE"] = "Training on a profession's window"
L["WN73_1_TEXT"] = "With What's Training installed, a profession's window has two side tabs: the bottom one lists what its trainer can teach you, the top one returns to the profession. Training tabs wear What's Training's own icons, on the spellbook too."
L["WN73_2_TITLE"] = "Loot in a fight"
L["WN73_2_TEXT"] = "Looting a corpse in a fight opens the loot window. From the second loot of a session on, the game had refused it with the Interface action failed because of an AddOn message."
L["WN73_3_TITLE"] = "Spellbook"
L["WN73_3_TEXT"] = "The micro button and the key close the book from the What's Training page, and a book closed there opens again. In a fight the book opens at the window row's start; it had opened far to the right when the map was open as the fight began."
L["WN73_4_TITLE"] = "Nameplate size per character"
L["WN73_4_TEXT"] = "Same size near and far applies each character's own choice when they log in. It took effect only after the box was toggled on that character. Turn it on in the options (/fcui), under Nameplates."
L["WN72_1_TITLE"] = "Dressing room"
L["WN72_1_TEXT"] = "The dressing room opens at the 1.x size. For the bigger room of later clients, turn on Large dressing room in the options (/fcui), under All windows; our windows make room beside it for its side panels."
L["WN72_2_TITLE"] = "Micro menu fade"
L["WN72_2_TEXT"] = "The micro menu can fade like the action bars: set Faded Opacity or Show Only On Hover in its edit mode dialog, and link it with the faded bars."
L["WN72_3_TITLE"] = "Guild window"
L["WN72_3_TEXT"] = "Add Member, Guild Information and the member right-click menu go through the game's own buttons and menu, so inviting, editing the info, removing, promoting and demoting work."
L["WN72_4_TITLE"] = "Who side tab"
L["WN72_4_TEXT"] = "The group finder's Who side tab is hidden for everyone. Turn off Hide Who side tab in the options (/fcui), under Social, to have it back."
L["WN72_5_TITLE"] = "Nameplate size"
L["WN72_5_TEXT"] = "Same size near and far keeps plates one size as in Classic Era, now through the game's own settings and kept per character, outside profiles. Turn it on in the options (/fcui), under Nameplates."
L["WN72_6_TITLE"] = "Fixes"
L["WN72_6_TEXT"] = "A long guild name ends in dots before the zone column, the trainer window scrolls a long description, Ctrl-click on a quest reward opens the dressing room, the totem bar's buttons wear the classic look, a quest's party count stays when quest levels are off, and What's Training's lists sit on a page of the spellbook with a Professions tab beside it."
L["WN71_1_TITLE"] = "Totem bar stays put"
L["WN71_1_TEXT"] = "A bar snapped to an action bar in edit mode, like the shaman's totem bar, keeps its spot once edit mode closes and after a reload."
L["WN71_2_TITLE"] = "Minimap button trays"
L["WN71_2_TEXT"] = "A minimap button tray from another addon can be moved again with ClassicUI Forever on."
L["WN71_3_TITLE"] = "Threat percent"
L["WN71_3_TEXT"] = "The threat percent over the target and focus stops at 999%, as Classic Era's did."
L["WN70_1_TITLE"] = "Linked bar fading"
L["WN70_1_TEXT"] = "Faded action bars can come back together: check Linked to other faded bars under each bar's Faded Opacity in edit mode, and the mouse on any of them shows them all (#255)."
L["WN70_2_TITLE"] = "Enchant glow"
L["WN70_2_TEXT"] = "The game's gold glow after a sharpening stone, oil or enchant is off, as Classic Era had none. To have it back, turn it on in the options (/fcui): Gold glow on enchant under Character sheet. It now runs along the window's border (#262)."
L["WN70_4_TITLE"] = "Titles tab"
L["WN70_4_TEXT"] = "The character window's side panel has the Titles tab again (#261). Talent icons fill their slots as in Classic Era (#260)."
L["WN70_3_TITLE"] = "Loot window on the controller"
L["WN70_3_TEXT"] = "With the controller, the d-pad moves through the loot window's items (#264)."
L["WN69_1_TITLE"] = "Our windows on the controller"
L["WN69_1_TEXT"] = "With the gamepad interface on, the classic spellbook, talents, quest log, collections, Legacy window and one bag work with the controller: the d-pad moves, A selects, B closes, and the buttons to press are shown under the window. The spellbook and talents open as their own windows again. In the quest log the list scrolls as you go, and Y opens the map."
L["WN69_2_TITLE"] = "Bind spells from the spellbook"
L["WN69_2_TEXT"] = "With the controller, press X on a spell in the classic spellbook, then the button for it; hold LT or RT for the side groups, as in the game's own book. Y opens the game's action bar editor."
L["WN69_3_TITLE"] = "Profession tabs hidden"
L["WN69_3_TEXT"] = "The tabs beside the professions window are hidden, as Classic Era had none. To have them back, turn them on in the options (/fcui): pick Profession tabs: on hover or always shown under Professions book. What's Training's list of recipes to learn opens from a side tab beside the book (#260)."
L["WN69_4_TITLE"] = "Smaller changes"
L["WN69_4_TEXT"] = "The chat window keeps its place when another addon resizes it by its top edge (#247). With the controller, the professions window's Spellbook and Collections tabs turn the page in place, and the character window's outline fits its frame."
L["WN68_1_TITLE"] = "Dual spec tabs on the talents window"
L["WN68_1_TEXT"] = "The two specs' tabs run down the talents window's edge, as Classic's did. Click one to look at that spec."
L["WN68_2_TITLE"] = "The world map's text at the game's size"
L["WN68_2_TEXT"] = "In the Classic header style the map's header, quest pane and Map Options read at 70% of the game's text size windowed. They are the game's size now, the quest pane is its full width, and the Continent and Zone labels sit beside their drop downs."
L["WN68_3_TITLE"] = "Quests on parchment in the map's pane"
L["WN68_3_TEXT"] = "The map's quest pane lists quests on the game's parchment. For the dark stone, uncheck List on the game's parchment under World map."
L["WN68_4_TITLE"] = "Addon buttons kept on the ring"
L["WN68_4_TEXT"] = "With Collect addon buttons on, Keep on the ring lists every addon button; check the ones that stay on the ring while the rest go into the bag. Collect addon buttons is off by default; turn it on in the options (/fcui), under Minimap."
L["WN68_5_TITLE"] = "No New Recipe Learned box"
L["WN68_5_TEXT"] = "The game's box that pops up as a profession teaches you something is gone, as 1.x had none. To have it back, turn it on in the options (/fcui): check Skill toast under Other."
L["WN68_6_TITLE"] = "Smaller changes"
L["WN68_6_TEXT"] = "A talent below its top rank is green whether or not you have points to spend, as Classic Era colors it. The social window's lists count their rows whole (#232), and the Damage numbers row is gone, as it only mirrored the game's own setting."
L["WN67_1_TITLE"] = "Minimap pieces stay on the minimap"
L["WN67_1_TEXT"] = "Every minimap piece's box in ClassicUI Forever Windows has a Stay on minimap check. Checked, the piece keeps its spot on the minimap. Uncheck it to drag the piece anywhere."
L["WN67_2_TITLE"] = "The Options window follows the theme"
L["WN67_2_TEXT"] = "Its border and Classic Era's pieces wear the dark, bronze or custom look, with no bronze left on its edges in the classic look."
L["WN67_3_TITLE"] = "The one bag's slots and header"
L["WN67_3_TEXT"] = "Empty slots show no bag icon, the search box reaches the Clean Up button, and the header band is whole."
L["WN67_4_TITLE"] = "The world map in a fight"
L["WN67_4_TEXT"] = "Opened during a fight, the map is sized by the addon alone, so another map addon can no longer set off a blocked-action error."
L["WN66_1_TITLE"] = "Tooltips are Classic Era's dark again"
L["WN66_1_TEXT"] = "Every tooltip wears Era's dark fill in every look. The game's lighter, bluer fill showed through from the second tooltip on, with a gap inside the border."
L["WN66_2_TITLE"] = "The minimap moves in Edit Mode again"
L["WN66_2_TEXT"] = "Dragging the minimap in Edit Mode keeps it in view and saves its new place."
L["WN66_3_TITLE"] = "The world map keeps its size in a fight"
L["WN66_3_TEXT"] = "Opened during a fight, the map is the size it is out of one, with or without the quest log."
L["WN65_1_TITLE"] = "Move all your windows at once"
L["WN65_1_TEXT"] = "ClassicUI Forever Windows has a Window row box: drag it, and every window that opens side by side moves there together."
L["WN65_2_TITLE"] = "Beast Training counts in training points again"
L["WN65_2_TEXT"] = "The pet trainer window shows your pet's training points and what each skill costs in points, and Train goes by them, as Classic Era's Beast Training did."

L["WN64_1_TITLE"] = "Fade your action bars"
L["WN64_1_TEXT"] = "Select a bar in Edit Mode: under the game's own settings for it, set its Faded Opacity or check Show Only On Hover. It comes back to full while the mouse is on it or a spell is dragged to it."
L["WN64_2_TITLE"] = "Nameplate error fixed"
L["WN64_2_TEXT"] = "With the game's own nameplates and another addon's nameplate auras, new nameplates no longer cause a Lua error."
L["WN64_3_TITLE"] = "Empty slots after the spellbook"
L["WN64_3_TEXT"] = "With Always Show Buttons off, your bars' empty slots show again for a spell or item you pick up after closing the spellbook."
L["WN64_4_TITLE"] = "ClassicUI Forever Windows fixes"
L["WN64_4_TEXT"] = "Its check in Edit Mode takes clicks again, and the world map's size there steps evenly from the size it opens at."

L["WN63_1_TITLE"] = "Loot tooltips beside the item"
L["WN63_1_TEXT"] = "In the loot window, an item's tooltip opens beside its icon, as in Classic Era, not past the window's right edge."

L["WN62_1_TITLE"] = "Spread your action bars"
L["WN62_1_TEXT"] = "Edit Mode's Icon Padding now spreads the buttons of every action bar. On Action Bar 1 the stone band widens with it, each button still on its socket."
L["WN62_2_TITLE"] = "Unwrap gifts in Collections"
L["WN62_2_TEXT"] = "Gift-wrapped mounts, pets and toys can be unwrapped in the classic Collections window: pick one and click Unwrap, or click a wrapped toy."
L["WN62_3_TITLE"] = "Tooltips as in Classic Era"
L["WN62_3_TEXT"] = "Tooltips in the classic look have Classic Era's background: the same dark color and see-through, where they were bluer and more solid."

L["WN61_1_TITLE"] = "Clearer size questions"
L["WN61_1_TEXT"] = "The questions and boxes about the interface size name the game's UI Scale and the percent they set, in fewer words."
L["WN60_1_TITLE"] = "Classic boss frames"
L["WN60_1_TEXT"] = "The boss frames of dungeon and raid fights wear the old dragon frame, with the level in its round ring and the cast bar beside or under the frame. To get the game's own back, uncheck Boss in the Frames list in the options (/fcui), under Unit frames."
L["WN60_2_TITLE"] = "Hide quality borders"
L["WN60_2_TEXT"] = "Items you wear on the character sheet can show without the colored border of their quality. It is off by default; turn it on in the options (/fcui), under Character sheet."
L["WN59_1_TITLE"] = "Less work for the game"
L["WN59_1_TEXT"] = "Nameplates do much less work when you change target, cast, gain or lose auras, or stand among other players. The target and focus frames and the Who list do less in the background too."
L["WN58_1_TITLE"] = "Era's town markers"
L["WN58_1_TEXT"] = "Revantusk Village and Cenarion Hold show on the continent maps only once you have explored their area, as in Classic Era."
L["WN57_1_TITLE"] = "Show bags with a click"
L["WN57_1_TEXT"] = "With Bag bar on backpack only, Ctrl-click the backpack to show the other bags or fold them away again; the arrow beside it is gone. Show bags with picks another click. To turn it on, pick Bag bar: backpack only in the options (/fcui), under Bags."
L["WN57_2_TITLE"] = "Hide key ring art"
L["WN57_2_TEXT"] = "Hide key ring art now also clears the key ring's slot on the classic bar, and it takes over from Hide key ring art too, keeping your pick. It is off by default; turn it on in the options (/fcui), under Bags."
L["WN57_3_TITLE"] = "Bag picks with Classic bar off"
L["WN57_3_TEXT"] = "With Classic bar off, picks the game's own bag bar cannot follow are grayed in the options, and their tooltip says why."
L["WN56_1_TITLE"] = "Faster Custom theme"
L["WN56_1_TEXT"] = "Switching the look or a part under Themed no longer stalls the game, and an unchecked part gets the game's own colors back. Custom theme is off by default; turn it on in the options (/fcui), under Look."
L["WN55_1_TITLE"] = "Bar texture"
L["WN55_1_TEXT"] = "A Bar texture pick under Unit frames for the health and mana bars: Classic, now drawn smoother, Raid frames, Solid or Skill bar."
L["WN55_2_TITLE"] = "Shop button"
L["WN55_2_TEXT"] = "The shop button can stand on the 1.x micro menu in a frame of its own. It is hidden by default: to show it, uncheck Shop under Hide micro buttons on the Action bars page of the options (/fcui)."
L["WN55_3_TITLE"] = "Spellbook button"
L["WN55_3_TEXT"] = "The spellbook button on the micro menu stays pressed while the spellbook shows your spells."
L["WN55_4_TITLE"] = "Fixes"
L["WN55_4_TEXT"] = "The social button's tooltip says Social, and a long window title keeps its title plate's ends."
L["WN54_1_TITLE"] = "Smoother options"
L["WN54_1_TEXT"] = "Changing an option no longer stutters: only the parts of the interface that option touches are laid out again."
L["WN54_2_TITLE"] = "Micro menu"
L["WN54_2_TEXT"] = "Micro buttons you hide stay hidden, a lone button left on the row stands at its end, and the row sits centered on the bar with no gap in its floor."
L["WN54_3_TITLE"] = "Minimap in instances"
L["WN54_3_TEXT"] = "With Rotate Minimap on, instances no longer show a second big ring around the minimap."
L["WN54_4_TITLE"] = "Housing button"
L["WN54_4_TEXT"] = "The housing button on the micro menu has a 1.x frame like the others."
L["WN54_5_TITLE"] = "Fixes"
L["WN54_5_TEXT"] = "After a reload in a fight the game's own XP bar frame no longer shows over the 1.x one, and a window size saved in Edit Mode can no longer push a window off the screen, such as a large world map."
L["WN53_1_TITLE"] = "Finer theme parts"
L["WN53_1_TEXT"] = "Under Custom theme, the Themed list splits into finer parts, such as cast bars, nameplates, the micro menu and menus, so you can keep any of them in the classic look. Custom theme is off by default; turn it on in the options (/fcui), under Look."
L["WN53_2_TITLE"] = "Right action bars"
L["WN53_2_TEXT"] = "With Classic bar off and the minimap made bigger in Edit Mode, action bars 4 and 5 on the right no longer shrink to about two thirds; they shrink only as much as the room under the minimap needs."
L["WN53_3_TITLE"] = "Custom color"
L["WN53_3_TEXT"] = "Clicking outside the color picker keeps the color you picked; Cancel or Escape still undoes it."
L["WN53_4_TITLE"] = "Theme fixes"
L["WN53_4_TEXT"] = "When the theme colors the game's windows, they no longer flash their own colors as they open, and the game menu's red buttons draw their ends right. Other addons' frames keep their own look; to color them too, turn on Other addons in the Themed list, in the options (/fcui) under Look."
L["WN52_1_TITLE"] = "Honor badge"
L["WN52_1_TEXT"] = "The player, target and focus frames can show the game's honor level badge in place of the 1.x faction emblem. Off by default; turn it on in the options (/fcui), under Unit frames."
L["WN52_2_TITLE"] = "Chat tabs on hover"
L["WN52_2_TEXT"] = "With chat tabs on hover, only the tabs of the chat window under the mouse show: the docked windows' tabs together, or a window you dragged out on its own."
L["WN52_3_TITLE"] = "Group finder eye"
L["WN52_3_TEXT"] = "Snap to minimap for the group finder eye is no longer in the options; it stays in the eye's Edit Mode settings."
L["WN52_4_TITLE"] = "Group finder eye"
L["WN52_4_TEXT"] = "Snap to minimap for the group finder eye moved from the options to its Group finder box in ClassicUI Forever Windows (edit mode), under Minimap. The box stays while the eye is off the rim, so you can turn it back on."
L["WN52_5_TITLE"] = "Damage flash tooltip"
L["WN52_5_TEXT"] = "The Damage flash tooltip says the red shows on the player frame's health bar. Damage flash is off by default; turn it on in the options (/fcui), under Unit frames."
L["WN51_1_TITLE"] = "Mastery and Versatility"
L["WN51_1_TEXT"] = "The character window's stats show Mastery and Versatility, under General."
L["WN51_2_TITLE"] = "Professions window"
L["WN51_2_TEXT"] = "The expansion pick is in the Filter menu now. The window opens where the game's other windows stand, with no gap after the spellbook, and its bottom border runs under the Create buttons."
L["WN51_3_TITLE"] = "One bag options"
L["WN51_3_TEXT"] = "The options under One bag only change the addon's bag windows, so they gray out while Bag windows is off. To use them, turn it on in the options (/fcui), under Bags."
L["WN51_4_TITLE"] = "Tab fixes"
L["WN51_4_TEXT"] = "On the professions and talents windows, the picked tab shows its whole face and the other tabs no longer show a black band."
L["WN50_1_TITLE"] = "Textured color"
L["WN50_1_TEXT"] = "Textured color, which keeps the art's texture in the theme's color, now colors whole windows, not only their metal: the stone of bags and tabs, search and input box borders, and the spellbook's page arrows, where a usable arrow is lighter than a spent one. Off by default; turn it on in the options (/fcui), under Look."
L["WN50_2_TITLE"] = "Themes on the game's windows"
L["WN50_2_TEXT"] = "Themes also color the game's own art left in the windows the addon restyles: the social window's tabs, scroll bars, search boxes, drop-downs such as the status picker, the money box, the guild roster's column headers, the communities chat box and the raid tab."
L["WN50_3_TITLE"] = "Bronze on retail"
L["WN50_3_TEXT"] = "The Bronze theme now colors the game's own window art too, which is silver on retail, as the other themes do."
L["WN50_4_TITLE"] = "Hide help buttons"
L["WN50_4_TEXT"] = "Hides the game's help buttons, the i at the top left of windows such as the map, professions and the spellbook, and the tutorial tips they pop. On by default; turn it off in the options (/fcui), under Other."
L["WN50_5_TITLE"] = "Hide Who side tab"
L["WN50_5_TEXT"] = "The group finder can drop its Who side tab, so Who is reached from the social window alone. On for new installs; if you used the addon before, turn it on in the options (/fcui), under Social."
L["WN50_6_TITLE"] = "Fixes"
L["WN50_6_TEXT"] = "The spellbook's portrait ring takes the Bronze theme instead of staying silver, and a page arrow that can turn again no longer keeps its spent color until you click elsewhere. Nameplates show the skull for friendly units of unknown level, as the target frame does. The inset border on the social window's Friends and Raid tabs takes the theme's color, and an error the theme could raise in a fight is gone."
